head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_1)은 @propval <true> 의 '다음 속성이 강제로 설정됩니다' 10종 + @propval <false (default)> + @spec1 을 담당한다.
//  - senseReader 연쇄(focusFlow) / sortHeaderDiv-sortable 연쇄(showSortableImage, sortEvent) / @spec2 는 _2 담당이므로 제외.
//  - '렌더링 측면 변경' 5줄은 _3, @spec3(setVisibleRowNum + initFixedHeightByRowNum) 은 _4 담당이므로 제외.
//  - description 은 _2 ~ _4 와 동일하게 유지(@description 첫 문장).
scwin.tData = {
    "description" : "[gridView > P > accessibility]<br/>GridView 에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시, senseReader=true 로 강제 설정되어 스크린 리더 대응 기능이 활성화됩니다.",
        "true 설정 시, focusMove='false' 로 강제 설정되어 방향키에 의한 Cell 이동이 차단됩니다. 단, senseReader=true 로 인해 Tab 키 이동은 허용됩니다.",
        "true 설정 시, keyMoveEditMode=true 로 강제 설정되어 Tab/Enter 키로 Cell 이동 시 자동 편집 모드로 진입합니다.",
        "true 설정 시, embeddedInput=true 로 강제 설정되어 Body Cell 내부에 입력 컴포넌트를 내장합니다.",
        "true 설정 시, autoResizeEmbeddedInput=true 로 강제 설정되어 embeddedInput 편집창 크기를 Cell 크기에 자동 맞춤합니다.",
        "true 설정 시, scrollFocus=true 로 강제 설정되어 스크롤바 영역으로 Tab 키에 의한 포커스 이동을 허용합니다.",
        "true 설정 시, titleAuto=true 로 강제 설정되어 Header 값을 Cell title 속성에 자동 반영합니다.",
        "true 설정 시, sortHeaderDiv=true 로 강제 설정되어 Header 에 정렬 아이콘을 button 요소로 표시합니다.",
        "true 설정 시, drawType='native' 로 강제 설정되어 가상 스크롤 대신 모든 Row 를 실제로 렌더링합니다.",
        "true 설정 시, visibleRowNum='all' 로 강제 설정되어 세로 스크롤 없이 모든 데이터를 표시합니다.",
        "false 설정 시, GridView 에 웹접근성 지원 기능을 적용하지 않습니다.",
        "미설정 시, GridView 에 웹접근성 지원 기능을 적용하지 않습니다.",
        "accessibility 속성은 Column 단위로 설정할 수 없으며 GridView 전체에 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 정적 select1(gdl_boolean)은 초기 selectedIndex 미적용 -> 기본값 명시 설정
    //  gdl_boolean 코드값 : 미설정="1" / true="2" / false="3"
    con_accessibility.setValue("2");        // 기본 시나리오 : accessibility=true (강제 설정 10종 확인)
    con_col1Accessibility.setValue("3");    // @spec1 대조 : GridView 와 반대값(false) 을 col1 에 부여해도 무시되는지 확인

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  accessibility 는 @dynamic N (렌더 시 결정) 이므로 con 변경 후
//  "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
//  - con_accessibility     : 공통 gdl_boolean -> getText() ('' 미설정 / 'true' / 'false')
//  - con_col1Accessibility : Body Column col1 에 accessibility 속성을 직접 부여 (@spec1 : Column 단위 설정 불가 대조)
//  - 전제 : 데이터 20행 + 그리드 높이 180px 고정 -> accessibility 미적용 시 세로 스크롤 표시(가상 스크롤),
//           accessibility=true 시 drawType=native + visibleRowNum=all 로 전 Row 실제 렌더 + 세로 스크롤 없음.
//  - sortable 은 설정하지 않는다(sortable 연쇄 강제는 _2 담당). sortHeaderDiv 는 옵션 적용값으로 확인한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vAcc = con_accessibility.getText();          // ''/'true'/'false'
    let vColAcc = con_col1Accessibility.getText();   // ''/'true'/'false'

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] 데이터 20행, 그리드 높이 180px 고정, sortable 미설정. Body Column 4종(text/text/select/calendar).';
    lbl += '\n[현재] accessibility=' + (vAcc === '' ? '(미설정)' : vAcc) + ', Body Column col1 의 accessibility 속성=' + (vColAcc === '' ? '(미설정)' : vColAcc);
    lbl += '\n[절차] con 선택 -> Target 재생성 -> [강제 설정 확인] 클릭. Column 단위 확인은 col1 값 선택 후 [Column 단위 설정 확인] 클릭.';
    lbl += '\n[확인] 출력 10줄에서 강제 설정 10종의 실제 적용값을 확인. accessibility=false/미설정 으로 재생성하면 각 속성이 기본값으로 남는지 대조.';
    lbl += '\n[참고] accessibility=true 는 전 Row 를 실제 렌더(drawType=native)하고 세로 스크롤을 없애므로(visibleRowNum=all), 그리드 높이(180px)를 넘는 Row 는 화면에서 잘려 보인다. 표시된 Row 수가 아니라 출력값(렌더된 Row 수 / 세로 스크롤 표시)으로 판정할 것.';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    let ns = $c.gcm.getNameSpace();

    // select 컬럼 itemset 용 코드/라벨 DataList
    let strGrade = '';
    strGrade += '<w2:dataList ' + ns + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // 본문 데이터리스트 (20행 -> 공통 헬퍼는 4행이라 인라인 생성)
    let strDl = '';
    strDl += '<w2:dataList ' + ns + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="date"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true"></w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);
    scwin.fillData();

    // 조건 설정 : accessibility 만 con 값으로 적용 ('' 미설정 시 속성 자체를 제외 -> 엔진 기본값 false)
    let properties = {};
    if (vAcc === 'true') {
        properties.accessibility = "true";
    } else if (vAcc === 'false') {
        properties.accessibility = "false";
    }
    let cList = $c.gcm.createCList(properties);

    // @spec1 대조용 : Body Column col1 에만 accessibility 속성을 직접 부여
    let colAccAttr = (vColAcc === '' ? '' : ' accessibility="' + vColAcc + '"');

    // target 생성
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    let grp_comp = $c.gcm.getTestGroup();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:560px;height:180px;">';
    s += '<w2:caption style="" id="caption1" value="accessibility 강제 설정 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="hrow1">';
    s += '<w2:column width="130" inputType="text" id="hcol1" value="col1 (text)"></w2:column>';
    s += '<w2:column width="130" inputType="text" id="hcol2" value="col2 (text)"></w2:column>';
    s += '<w2:column width="130" inputType="text" id="hcol3" value="col3 (select)"></w2:column>';
    s += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (calendar)"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="brow1">';
    s += '<w2:column width="130" inputType="text" dataType="text" id="col1" dataList="col1"' + colAccAttr + '></w2:column>';
    s += '<w2:column width="130" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="130" inputType="select" dataType="text" id="col3" dataList="col3">' + itemset + '</w2:column>';
    s += '<w2:column width="*" inputType="calendar" dataType="date" calendarValueType="yearMonthDate" displayFormat="yyyy-MM-dd" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 세로 스크롤(가상 스크롤) 대조를 위한 20행 데이터
scwin.fillData = function () {
    let grade = ["A", "B", "C"];
    let rows = [];
    for (let i = 1; i <= 20; i++) {
        rows.push({
            col1: "사과" + i,
            col2: "바나나" + i,
            col3: grade[i % 3],
            col4: "2025" + (i % 12 + 1 < 10 ? "0" + (i % 12 + 1) : (i % 12 + 1)) + "15"
        });
    }
    dlt_bind.setJSON(rows, false);
}



// 셀 내부에 입력 컴포넌트가 내장(embeddedInput) 되어 렌더된 Body Cell 수
scwin.getEmbeddedCellCount = function (gridEl) {
    let cnt = 0;
    let tds = gridEl.querySelectorAll("td[id*='_cell_']");
    tds.forEach(function (td) {
        if (td.querySelector('[class*="embedded"], .w2inputCalendar_div')) {
            cnt++;
        }
    });
    return cnt;
}



// Body Column 의 실제 적용된 embeddedInput 값 (embeddedInput 은 Column 단위 옵션)
scwin.getColumnEmbeddedInput = function (colId) {
    let ci = target1.cellInfoHash ? target1.cellInfoHash[colId] : null;
    if (!ci || !ci.options) {
        return "N/A";
    }
    return (ci.options.embeddedInput === "" ? "(미설정)" : String(ci.options.embeddedInput));
}



// (검증) 강제 설정 10종 확인
//  con_accessibility 선택 -> Target 재생성 -> 이 버튼으로 10종의 실제 적용값을 일괄 출력한다.
//  accessibility=true  -> 강제값 / accessibility=false, 미설정 -> 엔진 기본값 (@propval false, 미설정 검증)
scwin.btn_checkForced_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let gridEl = document.getElementById('mf_target1');
    if (typeof target1 === 'undefined' || !gridEl) {
        bottom.setReturnValue("grid(mf_target1) 미생성");
        return;
    }
    let o = target1.options;
    let sy = document.getElementById('mf_target1_scrollY_div');

    // 강제① senseReader
    bottom.setReturnValue("[강제① senseReader] " + o.senseReader + " (기본값 false)");
    // 강제② focusMove
    bottom.setReturnValue("[강제② focusMove] " + o.focusMove + " (기본값 true)");
    // 강제③ keyMoveEditMode
    bottom.setReturnValue("[강제③ keyMoveEditMode] " + o.keyMoveEditMode + " (기본값 false)");
    // 강제④ embeddedInput : Column 단위 옵션이므로 Body Column 적용값 + 실제 내장 렌더 셀 수로 확인
    bottom.setReturnValue("[강제④ embeddedInput] Body Column 적용값 col1=" + scwin.getColumnEmbeddedInput("col1")
        + ", col2=" + scwin.getColumnEmbeddedInput("col2")
        + ", col3=" + scwin.getColumnEmbeddedInput("col3")
        + ", col4=" + scwin.getColumnEmbeddedInput("col4")
        + " | 입력 컴포넌트가 내장된 Body Cell 수=" + scwin.getEmbeddedCellCount(gridEl) + " (미적용 시 false, 내장 0)");
    // 강제⑤ autoResizeEmbeddedInput
    bottom.setReturnValue("[강제⑤ autoResizeEmbeddedInput] " + o.autoResizeEmbeddedInput + " (기본값 false)");
    // 강제⑥ scrollFocus : 세로 스크롤 영역(scrollY_div) 의 tabIndex 부여 여부로 적용을 판정
    //  (최신 브라우저는 스크롤 div 를 native 로 포커스하므로 activeElement 로는 판정할 수 없다)
    bottom.setReturnValue("[강제⑥ scrollFocus] " + o.scrollFocus
        + " | 세로 스크롤 영역 tabIndex=" + (sy ? sy.getAttribute('tabIndex') : 'N/A') + " (0=엔진이 부여한 탭 정지점) (기본값 false)");
    // 강제⑦ titleAuto : Header 값이 Body Cell 의 title 속성에 자동 반영되는지 확인
    bottom.setReturnValue("[강제⑦ titleAuto] " + o.titleAuto + " | Cell(0,0) title=" + scwin.getCellTitle(gridEl) + " (기본값 false)");
    // 강제⑧ sortHeaderDiv
    bottom.setReturnValue("[강제⑧ sortHeaderDiv] " + o.sortHeaderDiv + " (기본값 false)");
    // 강제⑨ drawType : native 이면 가상 스크롤 없이 전 Row 가 실제 렌더된다
    bottom.setReturnValue("[강제⑨ drawType] " + o.drawType + " | 실제 렌더된 Row 수=" + scwin.getRenderedRowCount(gridEl)
        + " / 전체 데이터 " + dlt_bind.getRowCount() + "행 (기본값 virtual)");
    // 강제⑩ visibleRowNum : all 이면 세로 스크롤 없이 모든 데이터가 표시된다
    let hasVScroll = sy ? (sy.offsetHeight < sy.scrollHeight) : false;
    bottom.setReturnValue("[강제⑩ visibleRowNum] " + (o.visibleRowNum === "" ? "(미설정)" : o.visibleRowNum)
        + " | 세로 스크롤 표시=" + hasVScroll + " (기본값 미설정)");
}



// Body Cell(0,0) 의 title 속성 (titleAuto 적용 시 Header 값이 반영됨)
//  embeddedInput 이 적용되면 title 이 내장 입력 컴포넌트에 부여될 수 있어 td 와 내부 요소를 함께 확인한다.
scwin.getCellTitle = function (gridEl) {
    let td = gridEl.querySelector("td[id*='_cell_0_0']");
    if (!td) {
        return "N/A";
    }
    let t = td.getAttribute('title');
    if (!t) {
        let inner = td.querySelector("[title]");
        t = inner ? inner.getAttribute('title') : null;
    }
    return t ? t : "(없음)";
}



// 실제 렌더된 Body Row 수 (첫번째 Body Column 의 Cell 수로 계산)
scwin.getRenderedRowCount = function (gridEl) {
    return gridEl.querySelectorAll("td[id*='_cell_'][id$='_0']").length;
}



// (검증) @spec1 : Column 단위로 설정할 수 없으며 GridView 전체에 적용된다
//  Body Column col1 에만 accessibility 속성을 부여해도 무시되고, col1 의 적용 결과가
//  속성을 주지 않은 col2 와 동일하게 GridView 의 accessibility 설정을 따르는지 대조한다.
scwin.btn_checkColumnScope_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let gridEl = document.getElementById('mf_target1');
    if (typeof target1 === 'undefined' || !gridEl) {
        bottom.setReturnValue("grid(mf_target1) 미생성");
        return;
    }
    let ci1 = target1.cellInfoHash ? target1.cellInfoHash["col1"] : null;
    let colAcc = (ci1 && ci1.options && ci1.options.accessibility !== undefined) ? String(ci1.options.accessibility) : "(미설정)";
    let emb1 = scwin.getColumnEmbeddedInput("col1");
    let emb2 = scwin.getColumnEmbeddedInput("col2");
    bottom.setReturnValue("[@spec1] GridView accessibility=" + target1.options.accessibility
        + " | Body Column col1 에 설정한 accessibility=" + colAcc
        + " -> 적용 결과 col1 embeddedInput=" + emb1 + ", col2(미설정) embeddedInput=" + emb2
        + " -> " + (emb1 === emb2 ? "동일 : Column 단위 설정은 무시되고 GridView 설정이 전체에 적용됨" : "상이 : Column 단위 설정이 적용됨"));
}
